export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "雨は夕暮れに降りだし、亥の刻になってもやむ気配がなかった。", ruby: [{"start":0,"end":1,"reading":"あめ"},{"start":2,"end":4,"reading":"ゆうぐ"},{"start":6,"end":7,"reading":"ふ"},{"start":11,"end":12,"reading":"い"},{"start":13,"end":14,"reading":"こく"},{"start":21,"end":23,"reading":"けはい"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "山の雨は落ちてこない。横ざまに吹きつけてくる。ひとしきり、またひとしきりとすだれを叩くさまは、外で誰かが苛立たしげに本をめくっているようだった。", ruby: [{"start":0,"end":1,"reading":"やま"},{"start":2,"end":3,"reading":"あめ"},{"start":4,"end":5,"reading":"お"},{"start":11,"end":12,"reading":"よこ"},{"start":15,"end":16,"reading":"ふ"},{"start":41,"end":42,"reading":"たた"},{"start":47,"end":48,"reading":"そと"},{"start":49,"end":50,"reading":"だれ"},{"start":52,"end":54,"reading":"いらだ"},{"start":58,"end":59,"reading":"ほん"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は赤土の炉の前にしゃがみ、炭をひとつ足した。湯沸かしの水がちょうど泡を立てはじめたところで、細かな粒がひとつ、またひとつと浮かんでくる。", ruby: [{"start":0,"end":2,"reading":"しょうまん"},{"start":3,"end":5,"reading":"あかつち"},{"start":6,"end":7,"reading":"ろ"},{"start":8,"end":9,"reading":"まえ"},{"start":15,"end":16,"reading":"すみ"},{"start":20,"end":21,"reading":"た"},{"start":24,"end":26,"reading":"ゆわ"},{"start":29,"end":30,"reading":"みず"},{"start":35,"end":36,"reading":"あわ"},{"start":37,"end":38,"reading":"た"},{"start":48,"end":49,"reading":"こま"},{"start":51,"end":52,"reading":"つぶ"},{"start":63,"end":64,"reading":"う"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "蟹眼。まだ早い。", ruby: [{"start":0,"end":2,"reading":"かいがん"},{"start":5,"end":6,"reading":"はや"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠は振り向かなかった。帳場の奥に座って、古い急須を磨いている。かれこれ一刻近くになる。急須はとうに、顔が映るほど光っていた。", ruby: [{"start":0,"end":2,"reading":"ししょう"},{"start":3,"end":4,"reading":"ふ"},{"start":5,"end":6,"reading":"む"},{"start":12,"end":14,"reading":"ちょうば"},{"start":15,"end":16,"reading":"おく"},{"start":17,"end":18,"reading":"すわ"},{"start":21,"end":22,"reading":"ふる"},{"start":23,"end":25,"reading":"きゅうす"},{"start":26,"end":27,"reading":"みが"},{"start":36,"end":38,"reading":"いっこく"},{"start":38,"end":39,"reading":"ちか"},{"start":44,"end":46,"reading":"きゅうす"},{"start":51,"end":52,"reading":"かお"},{"start":53,"end":54,"reading":"うつ"},{"start":57,"end":58,"reading":"ひか"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）今夜は、何を磨いてもやけに長い。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"こんや"},{"start":9,"end":10,"reading":"なに"},{"start":11,"end":12,"reading":"みが"},{"start":18,"end":19,"reading":"なが"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "湯の音が太くなる。泡がひとまわり大きくなり、浮かんでは弾ける。", ruby: [{"start":0,"end":1,"reading":"ゆ"},{"start":2,"end":3,"reading":"おと"},{"start":4,"end":5,"reading":"ふと"},{"start":9,"end":10,"reading":"あわ"},{"start":16,"end":17,"reading":"おお"},{"start":22,"end":23,"reading":"う"},{"start":27,"end":28,"reading":"はじ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "魚眼。急須を温めろ。", ruby: [{"start":0,"end":2,"reading":"ぎょがん"},{"start":3,"end":5,"reading":"きゅうす"},{"start":6,"end":7,"reading":"あたた"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は湯沸かしを持ち上げ、煮えたぎる湯を急須の肌に回しかけた。湯気が立ちのぼり、顔いっぱいにまとわりつく。紫砂の急須は彼女よりも年上で、蓋には金継ぎの細いひびが一本走っている。眠っている蛇のようだった。", ruby: [{"start":0,"end":2,"reading":"しょうまん"},{"start":3,"end":5,"reading":"ゆわ"},{"start":8,"end":9,"reading":"も"},{"start":10,"end":11,"reading":"あ"},{"start":13,"end":14,"reading":"に"},{"start":18,"end":19,"reading":"ゆ"},{"start":20,"end":22,"reading":"きゅうす"},{"start":23,"end":24,"reading":"はだ"},{"start":25,"end":26,"reading":"まわ"},{"start":31,"end":33,"reading":"ゆげ"},{"start":34,"end":35,"reading":"た"},{"start":40,"end":41,"reading":"かお"},{"start":53,"end":55,"reading":"しさ"},{"start":56,"end":58,"reading":"きゅうす"},{"start":59,"end":61,"reading":"かのじょ"},{"start":64,"end":66,"reading":"としうえ"},{"start":68,"end":69,"reading":"ふた"},{"start":71,"end":73,"reading":"きんつ"},{"start":75,"end":76,"reading":"ほそ"},{"start":80,"end":82,"reading":"いっぽん"},{"start":82,"end":83,"reading":"はし"},{"start":88,"end":89,"reading":"ねむ"},{"start":93,"end":94,"reading":"へび"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "茶葉を入れ、湯を注ぎ、蓋をして、五つ数える。", ruby: [{"start":0,"end":2,"reading":"ちゃば"},{"start":3,"end":4,"reading":"い"},{"start":6,"end":7,"reading":"ゆ"},{"start":8,"end":9,"reading":"そそ"},{"start":11,"end":12,"reading":"ふた"},{"start":16,"end":17,"reading":"いつ"},{"start":18,"end":19,"reading":"かぞ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一煎目は、捨てる。", ruby: [{"start":0,"end":3,"reading":"いっせんめ"},{"start":5,"end":6,"reading":"す"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "茶は茶盤の下の竹の溝へ流れていった。琥珀色に、少し紅がさしている。", ruby: [{"start":0,"end":1,"reading":"ちゃ"},{"start":2,"end":4,"reading":"ちゃばん"},{"start":5,"end":6,"reading":"した"},{"start":7,"end":8,"reading":"たけ"},{"start":9,"end":10,"reading":"みぞ"},{"start":11,"end":12,"reading":"なが"},{"start":18,"end":21,"reading":"こはくいろ"},{"start":23,"end":24,"reading":"すこ"},{"start":25,"end":26,"reading":"べに"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）毎回、もったいないと思う。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"まいかい"},{"start":15,"end":16,"reading":"おも"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "もったいないか。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満はびくりとした。ひと言も口に出していないのに。", ruby: [{"start":0,"end":2,"reading":"しょうまん"},{"start":12,"end":13,"reading":"こと"},{"start":14,"end":15,"reading":"くち"},{"start":16,"end":17,"reading":"だ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "一煎目を捨てるとき、お前はいつも口がへの字になる。七年、ずっとだ。", ruby: [{"start":0,"end":3,"reading":"いっせんめ"},{"start":4,"end":5,"reading":"す"},{"start":11,"end":12,"reading":"まえ"},{"start":16,"end":17,"reading":"くち"},{"start":20,"end":21,"reading":"じ"},{"start":25,"end":27,"reading":"しちねん"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "茶葉は干され、炒られ、揉まれ、焙じられてここまで来る。埃もつく、手の汗もつく、道中の風もつく。一煎目がそれを持っていく。後に続くもののために、誰かが先に苦い思いをせねばならん。", ruby: [{"start":0,"end":2,"reading":"ちゃば"},{"start":3,"end":4,"reading":"ほ"},{"start":7,"end":8,"reading":"い"},{"start":11,"end":12,"reading":"も"},{"start":15,"end":16,"reading":"ほう"},{"start":24,"end":25,"reading":"く"},{"start":27,"end":28,"reading":"ほこり"},{"start":32,"end":33,"reading":"て"},{"start":34,"end":35,"reading":"あせ"},{"start":39,"end":41,"reading":"どうちゅう"},{"start":42,"end":43,"reading":"かぜ"},{"start":47,"end":50,"reading":"いっせんめ"},{"start":54,"end":55,"reading":"も"},{"start":60,"end":61,"reading":"あと"},{"start":62,"end":63,"reading":"つづ"},{"start":71,"end":72,"reading":"だれ"},{"start":74,"end":75,"reading":"さき"},{"start":76,"end":77,"reading":"にが"},{"start":78,"end":79,"reading":"おも"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "それじゃ、一煎目ばかり貧乏くじだ。", ruby: [{"start":5,"end":8,"reading":"いっせんめ"},{"start":11,"end":13,"reading":"びんぼう"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "うむ。貧乏くじだ。", ruby: [{"start":3,"end":5,"reading":"びんぼう"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠は古い急須を置き、戸口にちらりと目をやった。", ruby: [{"start":0,"end":2,"reading":"ししょう"},{"start":3,"end":4,"reading":"ふる"},{"start":5,"end":7,"reading":"きゅうす"},{"start":8,"end":9,"reading":"お"},{"start":11,"end":13,"reading":"とぐち"},{"start":18,"end":19,"reading":"め"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸の枠には、三本の刻み傷がある。いちばん低いのが小満のもので、横にいびつな「満」の字が彫ってある。上の二本はずっと高く、深く刻まれていた。ひとつは「硯」、もうひとつは「遅」。", ruby: [{"start":0,"end":1,"reading":"と"},{"start":2,"end":3,"reading":"わく"},{"start":6,"end":8,"reading":"さんぼん"},{"start":9,"end":10,"reading":"きざ"},{"start":11,"end":12,"reading":"きず"},{"start":20,"end":21,"reading":"ひく"},{"start":24,"end":26,"reading":"しょうまん"},{"start":31,"end":32,"reading":"よこ"},{"start":38,"end":39,"reading":"まん"},{"start":41,"end":42,"reading":"じ"},{"start":43,"end":44,"reading":"ほ"},{"start":49,"end":50,"reading":"うえ"},{"start":51,"end":53,"reading":"にほん"},{"start":57,"end":58,"reading":"たか"},{"start":60,"end":61,"reading":"ふか"},{"start":62,"end":63,"reading":"きざ"},{"start":74,"end":75,"reading":"けん"},{"start":84,"end":85,"reading":"ち"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）一度だけ、誰のなのか訊いたことがある。その日、師匠はお茶をひと壺、まるごと煮詰めて駄目にした。それきり訊いていない。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"いちど"},{"start":10,"end":11,"reading":"だれ"},{"start":15,"end":16,"reading":"き"},{"start":26,"end":27,"reading":"ひ"},{"start":28,"end":30,"reading":"ししょう"},{"start":32,"end":33,"reading":"ちゃ"},{"start":36,"end":37,"reading":"つぼ"},{"start":42,"end":44,"reading":"につ"},{"start":46,"end":48,"reading":"だめ"},{"start":56,"end":57,"reading":"き"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸を叩く音。", ruby: [{"start":0,"end":1,"reading":"と"},{"start":2,"end":3,"reading":"たた"},{"start":4,"end":5,"reading":"おと"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三度。強くも弱くもなく、力加減を測ったように。", ruby: [{"start":0,"end":2,"reading":"さんど"},{"start":3,"end":4,"reading":"つよ"},{"start":6,"end":7,"reading":"よわ"},{"start":12,"end":15,"reading":"ちからかげん"},{"start":16,"end":17,"reading":"はか"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満が閂を外すと、風雨がなだれこんだ。灯火は半分に縮み、また持ちなおした。", ruby: [{"start":0,"end":2,"reading":"しょうまん"},{"start":3,"end":4,"reading":"かんぬき"},{"start":5,"end":6,"reading":"はず"},{"start":9,"end":11,"reading":"ふうう"},{"start":19,"end":21,"reading":"ともしび"},{"start":22,"end":24,"reading":"はんぶん"},{"start":25,"end":26,"reading":"ちぢ"},{"start":30,"end":31,"reading":"も"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸口に、男がひとり立っていた。笠を目深にかぶり、蓑からは水がしたたっている。背中には、油紙で包んだ細長いものを負っていた。", ruby: [{"start":0,"end":2,"reading":"とぐち"},{"start":4,"end":5,"reading":"おとこ"},{"start":9,"end":10,"reading":"た"},{"start":15,"end":16,"reading":"かさ"},{"start":17,"end":19,"reading":"まぶか"},{"start":24,"end":25,"reading":"みの"},{"start":28,"end":29,"reading":"みず"},{"start":38,"end":40,"reading":"せなか"},{"start":43,"end":45,"reading":"あぶらがみ"},{"start":46,"end":47,"reading":"つつ"},{"start":49,"end":51,"reading":"ほそなが"},{"start":55,"end":56,"reading":"お"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）剣だ。どれだけ厚く包んでも、あの形は剣だ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"けん"},{"start":12,"end":13,"reading":"あつ"},{"start":14,"end":15,"reading":"つつ"},{"start":21,"end":22,"reading":"かたち"},{"start":23,"end":24,"reading":"けん"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "温伯。", ruby: [{"start":0,"end":2,"reading":"おんはく"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は小満を見なかった。彼女の肩越しに、帳場の奥の老人を見ていた。", ruby: [{"start":0,"end":1,"reading":"おとこ"},{"start":2,"end":4,"reading":"しょうまん"},{"start":5,"end":6,"reading":"み"},{"start":11,"end":13,"reading":"かのじょ"},{"start":14,"end":16,"reading":"かたご"},{"start":19,"end":21,"reading":"ちょうば"},{"start":22,"end":23,"reading":"おく"},{"start":24,"end":26,"reading":"ろうじん"},{"start":27,"end":28,"reading":"み"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "入れ。床が濡れる。履物を脱げ。", ruby: [{"start":0,"end":1,"reading":"はい"},{"start":3,"end":4,"reading":"ゆか"},{"start":5,"end":6,"reading":"ぬ"},{"start":9,"end":11,"reading":"はきもの"},{"start":12,"end":13,"reading":"ぬ"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は一瞬、動きを止めた。その言葉で何かを思い出したかのように。それから身をかがめて履物を脱ぎ、笠を戸口の脇の釘に掛けた。その釘が何のためにあるのか、小満はずっと知らなかった。", ruby: [{"start":0,"end":1,"reading":"おとこ"},{"start":2,"end":4,"reading":"いっしゅん"},{"start":5,"end":6,"reading":"うご"},{"start":8,"end":9,"reading":"と"},{"start":14,"end":16,"reading":"ことば"},{"start":17,"end":18,"reading":"なに"},{"start":20,"end":21,"reading":"おも"},{"start":22,"end":23,"reading":"だ"},{"start":35,"end":36,"reading":"み"},{"start":41,"end":43,"reading":"はきもの"},{"start":44,"end":45,"reading":"ぬ"},{"start":47,"end":48,"reading":"かさ"},{"start":49,"end":51,"reading":"とぐち"},{"start":52,"end":53,"reading":"わき"},{"start":54,"end":55,"reading":"くぎ"},{"start":56,"end":57,"reading":"か"},{"start":62,"end":63,"reading":"くぎ"},{"start":64,"end":65,"reading":"なん"},{"start":74,"end":76,"reading":"しょうまん"},{"start":80,"end":81,"reading":"し"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）今、わかった。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"いま"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "笠の下から現れたのは、三十がらみの顔だった。眉骨が高く、唇を固く結んでいる。その線は、鞘に納められた刃のようだった。", ruby: [{"start":0,"end":1,"reading":"かさ"},{"start":2,"end":3,"reading":"した"},{"start":5,"end":6,"reading":"あらわ"},{"start":11,"end":13,"reading":"さんじゅう"},{"start":17,"end":18,"reading":"かお"},{"start":22,"end":24,"reading":"びこつ"},{"start":25,"end":26,"reading":"たか"},{"start":28,"end":29,"reading":"くちびる"},{"start":30,"end":31,"reading":"かた"},{"start":32,"end":33,"reading":"むす"},{"start":40,"end":41,"reading":"せん"},{"start":43,"end":44,"reading":"さや"},{"start":45,"end":46,"reading":"おさ"},{"start":50,"end":51,"reading":"やいば"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "小満、茶を。", ruby: [{"start":0,"end":2,"reading":"しょうまん"},{"start":3,"end":4,"reading":"ちゃ"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は炉のそばに戻り、もう一度急須を温めた。男は窓ぎわの卓につき、油紙の包みを膝の上に横たえた。包みは解かなかった。", ruby: [{"start":0,"end":2,"reading":"しょうまん"},{"start":3,"end":4,"reading":"ろ"},{"start":8,"end":9,"reading":"もど"},{"start":13,"end":15,"reading":"いちど"},{"start":15,"end":17,"reading":"きゅうす"},{"start":18,"end":19,"reading":"あたた"},{"start":22,"end":23,"reading":"おとこ"},{"start":24,"end":25,"reading":"まど"},{"start":28,"end":29,"reading":"たく"},{"start":33,"end":35,"reading":"あぶらがみ"},{"start":36,"end":37,"reading":"つつ"},{"start":39,"end":40,"reading":"ひざ"},{"start":41,"end":42,"reading":"うえ"},{"start":43,"end":44,"reading":"よこ"},{"start":48,"end":49,"reading":"つつ"},{"start":51,"end":52,"reading":"と"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "あいつは来ましたか。", ruby: [{"start":4,"end":5,"reading":"き"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "まだだ。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "来るでしょうか。", ruby: [{"start":0,"end":1,"reading":"く"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "来る。ここはあいつの家だ。", ruby: [{"start":0,"end":1,"reading":"く"},{"start":10,"end":11,"reading":"いえ"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "とうに違います。", ruby: [{"start":3,"end":4,"reading":"ちが"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "師匠は何も返さなかった。小満が一煎目を竹の溝へ捨てると、男の視線はその茶の筋をしばらく追い、また戻った。", ruby: [{"start":0,"end":2,"reading":"ししょう"},{"start":3,"end":4,"reading":"なに"},{"start":5,"end":6,"reading":"かえ"},{"start":12,"end":14,"reading":"しょうまん"},{"start":15,"end":18,"reading":"いっせんめ"},{"start":19,"end":20,"reading":"たけ"},{"start":21,"end":22,"reading":"みぞ"},{"start":23,"end":24,"reading":"す"},{"start":28,"end":29,"reading":"おとこ"},{"start":30,"end":32,"reading":"しせん"},{"start":35,"end":36,"reading":"ちゃ"},{"start":37,"end":38,"reading":"すじ"},{"start":43,"end":44,"reading":"お"},{"start":48,"end":49,"reading":"もど"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二煎目は茶海で濃さをならし、男の前の小さな杯に注いだ。", ruby: [{"start":0,"end":3,"reading":"にせんめ"},{"start":4,"end":6,"reading":"ちゃかい"},{"start":7,"end":8,"reading":"こ"},{"start":14,"end":15,"reading":"おとこ"},{"start":16,"end":17,"reading":"まえ"},{"start":18,"end":19,"reading":"ちい"},{"start":21,"end":22,"reading":"さかずき"},{"start":23,"end":24,"reading":"そそ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "夜明けに、一線関で。", ruby: [{"start":0,"end":2,"reading":"よあ"},{"start":5,"end":8,"reading":"いっせんかん"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "知っている。あいつが人に託してよこした手紙は、わしも読んだ。", ruby: [{"start":0,"end":1,"reading":"し"},{"start":10,"end":11,"reading":"ひと"},{"start":12,"end":13,"reading":"たく"},{"start":19,"end":21,"reading":"てがみ"},{"start":26,"end":27,"reading":"よ"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "止めないのですか。", ruby: [{"start":0,"end":1,"reading":"と"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "一度は止めた、お前たちを。止められんものを、二度は止めん。", ruby: [{"start":0,"end":2,"reading":"いちど"},{"start":3,"end":4,"reading":"と"},{"start":8,"end":9,"reading":"まえ"},{"start":13,"end":14,"reading":"と"},{"start":22,"end":24,"reading":"にど"},{"start":25,"end":26,"reading":"と"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は杯を手に取ったが、飲まずに、ただ握っていた。湯気が指のあいだを這いのぼっていく。", ruby: [{"start":0,"end":1,"reading":"おとこ"},{"start":2,"end":3,"reading":"さかずき"},{"start":4,"end":5,"reading":"て"},{"start":6,"end":7,"reading":"と"},{"start":11,"end":12,"reading":"の"},{"start":18,"end":19,"reading":"にぎ"},{"start":24,"end":26,"reading":"ゆげ"},{"start":27,"end":28,"reading":"ゆび"},{"start":33,"end":34,"reading":"は"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "十年前のあの晩、私は関で白鷺門の門主の息子と剣を交えました。相手は負けました。私は剣を納め、息の根は止めずにおきました。", ruby: [{"start":0,"end":3,"reading":"じゅうねんまえ"},{"start":6,"end":7,"reading":"ばん"},{"start":8,"end":9,"reading":"わたし"},{"start":10,"end":11,"reading":"せき"},{"start":12,"end":15,"reading":"はくろもん"},{"start":16,"end":18,"reading":"もんしゅ"},{"start":19,"end":21,"reading":"むすこ"},{"start":22,"end":23,"reading":"けん"},{"start":24,"end":25,"reading":"まじ"},{"start":30,"end":32,"reading":"あいて"},{"start":33,"end":34,"reading":"ま"},{"start":39,"end":40,"reading":"わたし"},{"start":41,"end":42,"reading":"けん"},{"start":43,"end":44,"reading":"おさ"},{"start":46,"end":47,"reading":"いき"},{"start":48,"end":49,"reading":"ね"},{"start":50,"end":51,"reading":"と"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "夜が明けると、男はその場で死んでいました。", ruby: [{"start":0,"end":1,"reading":"よ"},{"start":2,"end":3,"reading":"あ"},{"start":7,"end":8,"reading":"おとこ"},{"start":11,"end":12,"reading":"ば"},{"start":13,"end":14,"reading":"し"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "阿遅はその夜のうちに出ていきました。私の剣を持ち去り、自分の剣を置いて、戸口にひと言刻んで。――殺したのは俺だ、と。", ruby: [{"start":0,"end":2,"reading":"あち"},{"start":5,"end":6,"reading":"よる"},{"start":10,"end":11,"reading":"で"},{"start":18,"end":19,"reading":"わたし"},{"start":20,"end":21,"reading":"けん"},{"start":22,"end":23,"reading":"も"},{"start":24,"end":25,"reading":"さ"},{"start":27,"end":29,"reading":"じぶん"},{"start":30,"end":31,"reading":"けん"},{"start":32,"end":33,"reading":"お"},{"start":36,"end":38,"reading":"とぐち"},{"start":41,"end":42,"reading":"こと"},{"start":42,"end":43,"reading":"きざ"},{"start":48,"end":49,"reading":"ころ"},{"start":53,"end":54,"reading":"おれ"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それを語るあいだ、声には少しの抑揚もなかった。他人の書いた書付を読みあげているようだった。", ruby: [{"start":3,"end":4,"reading":"かた"},{"start":9,"end":10,"reading":"こえ"},{"start":12,"end":13,"reading":"すこ"},{"start":15,"end":17,"reading":"よくよう"},{"start":23,"end":25,"reading":"たにん"},{"start":26,"end":27,"reading":"か"},{"start":29,"end":31,"reading":"かきつけ"},{"start":32,"end":33,"reading":"よ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "理由を訊きに来たのではありません。十年はもう十分に長い。けりをつけに来ただけです。", ruby: [{"start":0,"end":2,"reading":"りゆう"},{"start":3,"end":4,"reading":"き"},{"start":6,"end":7,"reading":"き"},{"start":17,"end":19,"reading":"じゅうねん"},{"start":22,"end":24,"reading":"じゅうぶん"},{"start":25,"end":26,"reading":"なが"},{"start":34,"end":35,"reading":"き"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は茶を飲みほし、杯をそっと卓に戻した。それから顔を上げ、はじめて正面から小満を見た。", ruby: [{"start":0,"end":1,"reading":"おとこ"},{"start":2,"end":3,"reading":"ちゃ"},{"start":4,"end":5,"reading":"の"},{"start":9,"end":10,"reading":"さかずき"},{"start":14,"end":15,"reading":"たく"},{"start":16,"end":17,"reading":"もど"},{"start":24,"end":25,"reading":"かお"},{"start":26,"end":27,"reading":"あ"},{"start":33,"end":35,"reading":"しょうめん"},{"start":37,"end":39,"reading":"しょうまん"},{"start":40,"end":41,"reading":"み"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "お前は？", ruby: [{"start":1,"end":2,"reading":"まえ"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "小満です。", ruby: [{"start":0,"end":2,"reading":"しょうまん"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "節気か。", ruby: [{"start":0,"end":2,"reading":"せっき"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "拾った日が、小満だった。", ruby: [{"start":0,"end":1,"reading":"ひろ"},{"start":3,"end":4,"reading":"ひ"},{"start":6,"end":8,"reading":"しょうまん"}], background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "……私を拾った日、師匠は墨を磨っていた。阿遅を拾った日は、一歩遅れた。", ruby: [{"start":2,"end":3,"reading":"わたし"},{"start":4,"end":5,"reading":"ひろ"},{"start":7,"end":8,"reading":"ひ"},{"start":9,"end":11,"reading":"ししょう"},{"start":12,"end":13,"reading":"すみ"},{"start":14,"end":15,"reading":"す"},{"start":20,"end":22,"reading":"あち"},{"start":23,"end":24,"reading":"ひろ"},{"start":26,"end":27,"reading":"ひ"},{"start":29,"end":31,"reading":"いっぽ"},{"start":31,"end":32,"reading":"おく"}], background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "男は戸の枠の二本の刻み傷を、長いあいだ見ていた。それから立ち上がり、二階へ上がっていった。", ruby: [{"start":0,"end":1,"reading":"おとこ"},{"start":2,"end":3,"reading":"と"},{"start":4,"end":5,"reading":"わく"},{"start":6,"end":8,"reading":"にほん"},{"start":9,"end":10,"reading":"きざ"},{"start":11,"end":12,"reading":"きず"},{"start":14,"end":15,"reading":"なが"},{"start":19,"end":20,"reading":"み"},{"start":28,"end":29,"reading":"た"},{"start":30,"end":31,"reading":"あ"},{"start":34,"end":36,"reading":"にかい"},{"start":37,"end":38,"reading":"あ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "油紙の包みは、ずっと背負ったままだった。一度も下ろさなかった。", ruby: [{"start":0,"end":2,"reading":"あぶらがみ"},{"start":3,"end":4,"reading":"つつ"},{"start":10,"end":12,"reading":"せお"},{"start":20,"end":22,"reading":"いちど"},{"start":23,"end":24,"reading":"お"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）あの人が背負っているのは、別の人の剣だ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":7,"end":8,"reading":"ひと"},{"start":9,"end":11,"reading":"せお"},{"start":18,"end":19,"reading":"べつ"},{"start":20,"end":21,"reading":"ひと"},{"start":22,"end":23,"reading":"けん"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）十年も。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"じゅうねん"}], background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
];
